// The language server: handles the messages of the protocol and answers them. It does not know where the messages come
// from, so that the tests can talk to it without a process.
#pragma once
#include <filesystem>
#include <functional>
#include <map>
#include <memory>
#include <set>
#include <string>
#include <vector>
#include "commands.hpp"
#include "document.hpp"
#include "json.hpp"
#include "keywords.hpp"

namespace blitz::lsp {
	class server {
		public:
		using sender = std::function<void(json const&)>;

		server(sender send, std::filesystem::path commands_file, std::filesystem::path userlibs_dir);
		~server();

		/** Handles one message. Returns false after `exit`. */
		bool handle(json const& message);

		/** Analyses the documents that changed since the last time. The caller does this when no message is waiting. */
		void idle();

		bool has_pending_work() const { return !_dirty.empty(); }
		int  exit_code() const { return _shutdown ? 0 : 1; }

		private:
		struct diagnostic {
			std::filesystem::path file;
			uint64_t line = 0, column = 0, length = 0; // 1-based, bytes
			int                   severity = 1;
			std::string           code;
			std::string           message;
			std::string           notice;
			std::vector<std::pair<std::pair<uint64_t, uint64_t>, std::pair<uint64_t, uint64_t>>> edit_ranges;
			std::vector<std::string> edit_texts;
			std::vector<std::filesystem::path> edit_files;
		};

		struct symbol {
			enum class kind { function, type, field, variable, constant, label } what;
			std::string           name; // As written
			std::string           lower;
			std::filesystem::path file;
			uint64_t              line = 0, column = 0;       // Of the name
			uint64_t              end_line = 0, end_column = 0; // Of the whole declaration, 0 if not known
			std::string           container; // The type of a field
		};

		struct state {
			std::string                                    uri;
			std::string                                    key;
			std::filesystem::path                          path;
			std::unique_ptr<document>                      doc;
			std::vector<symbol>                            symbols; // Of the main file and what it includes, from the last time that it parsed
			std::vector<diagnostic>                        diagnostics;
			std::set<std::string>                          published; // URIs that we sent diagnostics for
		};

		void reply(json const& id, json result);
		void fail(json const& id, int code, std::string const& message);
		void notify(std::string const& method, json params);

		json initialize(json const& params);
		void open(json const& params);
		void change(json const& params);
		void close(json const& params);
		void configuration(json const& settings);

		void analyze(state& s);
		void publish(state& s);

		document*      document_for(std::filesystem::path const& file);
		state*         find(std::string const& uri);
		json           location_of(symbol const& s);
		json           symbols_of(state& s);
		json           definition(json const& params);
		json           hover(json const& params);
		json           completion(json const& params);
		json           format(json const& params);
		json           rename(json const& params);
		json           prepare_rename(json const& params);
		json           references(json const& params);
		json           code_actions(json const& params);
		json           edit_to(state& s, std::string const& result);
		std::string    tidy(state& s, bool& ok);
		json           range_json(range r) const;
		json           range_of(std::filesystem::path const& file, uint64_t line, uint64_t column, uint64_t length);
		std::string    describe(word const& w, state& s, size_t offset);

		sender                          _send;
		command_table                   _commands;
		std::filesystem::path           _userlibs_dir;
		std::vector<keywords::user_function> _userlibs;
		std::map<std::string, std::unique_ptr<state>> _states; // By uri
		std::set<std::string>           _dirty;
		std::map<std::string, std::unique_ptr<document>> _files; // Files read for symbols, by path
		int                             _warning_level = 2;
		bool                            _shutdown      = false;
		bool                            _exit          = false;
	};

	std::string path_from_uri(std::string const& uri);
	std::string uri_from_path(std::string const& path);
	std::string path_key(std::filesystem::path const& path);
} // namespace blitz::lsp
